// Package gen emits the C side of the PHP bindings from a surface.Model: the
// cgo wrapper file compiled into the c-shared library, the FFI-parsable C
// header, and a JSON manifest describing what was bound and what was not.
//
// Every emitter is a pure function of the model. The same model always yields
// the same bytes, so the generated files can be committed and a drift check is
// a byte comparison. Nothing here reads the clock, the filesystem, or the
// environment.
package gen

import (
	"fmt"
	"go/format"
	"sort"
	"strings"

	"github.com/skrashevich/encx-cli/bindings/php/internal/surface"
)

const (
	// generator names this tool in every generated file.
	generator = "encxphpgen"
	// marker is the first line of every generated Go and C file. It matches
	// the canonical `^// Code generated .* DO NOT EDIT\.$` regexp that Go
	// tooling uses to recognise generated sources.
	marker = "// Code generated by " + generator + ". DO NOT EDIT."
	// rtImportPath is the hand-written runtime the wrappers call into. It is
	// spelled out rather than derived from the model, because the model
	// describes the bound package, not this generator's own sibling.
	rtImportPath = "github.com/skrashevich/encx-cli/bindings/php/internal/rt"
	// handleParam is the C parameter carrying the opaque client handle that
	// every method takes in first position.
	handleParam = "handle"
)

// group orders the sections of the generated header.
type group int

const (
	groupConstructor group = iota
	groupMethod
	groupFunction
)

// bound pairs a bindable symbol with the section it belongs to, which decides
// whether it takes a handle and what it is called on.
type bound struct {
	fn    surface.Func
	group group
}

func (b bound) isMethod() bool { return b.group == groupMethod }

// bindings returns every bindable symbol of m sorted by C symbol name.
func bindings(m *surface.Model) []bound {
	out := make([]bound, 0, len(m.Constructors)+len(m.Methods)+len(m.Functions))
	for _, fn := range m.Constructors {
		out = append(out, bound{fn: fn, group: groupConstructor})
	}
	for _, fn := range m.Methods {
		out = append(out, bound{fn: fn, group: groupMethod})
	}
	for _, fn := range m.Functions {
		out = append(out, bound{fn: fn, group: groupFunction})
	}
	sortBindings(out)
	return out
}

func sortBindings(b []bound) {
	sort.SliceStable(b, func(i, j int) bool { return b[i].fn.CName < b[j].fn.CName })
}

// CgoFile returns the contents of bindings/php/cshared/exports_gen.go.
func CgoFile(m *surface.Model) ([]byte, error) {
	if m == nil {
		return nil, fmt.Errorf("gen: nil model")
	}

	var b strings.Builder
	b.WriteString(marker + "\n\n")
	b.WriteString("package main\n\n")
	// Only declarations may appear in the preamble of a file carrying
	// //export directives; a definition here would make cgo refuse the file.
	b.WriteString("/*\n")
	b.WriteString("#include <stdlib.h>\n")
	b.WriteString("*/\n")
	b.WriteString("import \"C\"\n\n")
	b.WriteString("import (\n")
	fmt.Fprintf(&b, "\t%s%q\n", packageAlias(m), m.ImportPath)
	fmt.Fprintf(&b, "\t%q\n", rtImportPath)
	b.WriteString(")\n")

	for _, bd := range bindings(m) {
		b.WriteString("\n")
		if err := writeWrapper(&b, m, bd); err != nil {
			return nil, err
		}
	}

	out, err := format.Source([]byte(b.String()))
	if err != nil {
		return nil, fmt.Errorf("gen: format generated cgo file: %w", err)
	}
	return out, nil
}

// packageAlias returns the import alias needed to refer to the bound package
// by m.Package, or an empty string when the import path already ends in it.
func packageAlias(m *surface.Model) string {
	base := m.ImportPath
	if i := strings.LastIndex(base, "/"); i >= 0 {
		base = base[i+1:]
	}
	if base == m.Package {
		return ""
	}
	return m.Package + " "
}

// writeWrapper emits the doc comment, the //export directive and the body of
// one wrapper.
func writeWrapper(b *strings.Builder, m *surface.Model, bd bound) error {
	fn := bd.fn

	// The C parameter names become Go identifiers in the wrapper, so the
	// locals the body needs are picked around them.
	sc := newScope()
	var params []string
	if bd.isMethod() {
		sc.reserve(handleParam)
		params = append(params, handleParam+" C.longlong")
	}
	for _, p := range fn.Params {
		cn := surface.SnakeCase(p.Name)
		sc.reserve(cn)
		switch p.Type {
		case surface.TypeString:
			params = append(params, cn+" *C.char")
		case surface.TypeInt64:
			params = append(params, cn+" C.longlong")
		case surface.TypeBool:
			params = append(params, cn+" C.int")
		case surface.TypeBytes:
			sc.reserve(cn + "_len")
			params = append(params, cn+" *C.char", cn+"_len C.longlong")
		default:
			return fmt.Errorf("gen: %s: parameter %q has type %s, which has no C representation", fn.CName, p.Name, p.Type)
		}
	}

	handleVar := sc.take("handle")
	clientVar := sc.take("client")
	errVar := sc.take("err")
	valueVar := sc.take("value")

	writeDoc(b, fn.Doc)
	fmt.Fprintf(b, "//export %s\n", fn.CName)
	fmt.Fprintf(b, "func %s(%s) *C.char {\n", fn.CName, strings.Join(params, ", "))

	callee := m.Package + "." + fn.Name
	if bd.isMethod() {
		callee = clientVar + "." + fn.Name
		fmt.Fprintf(b, "\t%s, %s := rt.Default.Get(int64(%s))\n", clientVar, errVar, handleParam)
		writeFail(b, errVar)
	}

	call := callee + "(" + strings.Join(callArgs(fn), ", ") + ")"

	switch fn.Result.Kind {
	case surface.KindVoid:
		fmt.Fprintf(b, "\t%s\n", call)
		b.WriteString("\treturn cEnvelope(rt.OKVoid())\n")
	case surface.KindError:
		assign := ":="
		if bd.isMethod() {
			// err is already declared by the handle lookup above.
			assign = "="
		}
		fmt.Fprintf(b, "\tif %s %s %s; %s != nil {\n", errVar, assign, call, errVar)
		fmt.Fprintf(b, "\t\treturn cEnvelope(rt.Fail(%s))\n", errVar)
		b.WriteString("\t}\n")
		b.WriteString("\treturn cEnvelope(rt.OKVoid())\n")
	case surface.KindValue:
		fmt.Fprintf(b, "\treturn cEnvelope(rt.OK(%s))\n", call)
	case surface.KindValueErr, surface.KindJSONStruct:
		fmt.Fprintf(b, "\t%s, %s := %s\n", valueVar, errVar, call)
		writeFail(b, errVar)
		fmt.Fprintf(b, "\treturn cEnvelope(rt.OK(%s))\n", valueVar)
	case surface.KindHandle:
		fmt.Fprintf(b, "\t%s, %s := rt.Default.Add(%s)\n", handleVar, errVar, call)
		writeFail(b, errVar)
		fmt.Fprintf(b, "\treturn cEnvelope(rt.OK(%s))\n", handleVar)
	default:
		return fmt.Errorf("gen: %s: unknown result kind %d", fn.CName, fn.Result.Kind)
	}

	b.WriteString("}\n")
	return nil
}

func writeFail(b *strings.Builder, errVar string) {
	fmt.Fprintf(b, "\tif %s != nil {\n", errVar)
	fmt.Fprintf(b, "\t\treturn cEnvelope(rt.Fail(%s))\n", errVar)
	b.WriteString("\t}\n")
}

// callArgs converts each C parameter back to the Go value the bound function
// expects.
func callArgs(fn surface.Func) []string {
	args := make([]string, 0, len(fn.Params))
	for _, p := range fn.Params {
		cn := surface.SnakeCase(p.Name)
		switch p.Type {
		case surface.TypeString:
			args = append(args, "C.GoString("+cn+")")
		case surface.TypeInt64:
			args = append(args, "int64("+cn+")")
		case surface.TypeBool:
			args = append(args, cn+" != 0")
		case surface.TypeBytes:
			args = append(args, "cBytes("+cn+", "+cn+"_len)")
		}
	}
	return args
}

// writeDoc emits the Go doc comment of a bound symbol, followed by the blank
// comment line that separates prose from the //export directive.
func writeDoc(b *strings.Builder, doc string) {
	if strings.TrimSpace(doc) == "" {
		return
	}
	for _, line := range strings.Split(doc, "\n") {
		line = strings.TrimRight(line, " \t")
		if line == "" {
			b.WriteString("//\n")
			continue
		}
		b.WriteString("// " + line + "\n")
	}
	b.WriteString("//\n")
}

// scope hands out Go identifiers that cannot collide with the wrapper's
// parameters or with each other.
type scope struct {
	used map[string]bool
}

func newScope() *scope { return &scope{used: map[string]bool{}} }

func (s *scope) reserve(name string) { s.used[name] = true }

// take returns base, or base with the lowest suffix from 2 up that is free.
func (s *scope) take(base string) string {
	name := base
	for i := 2; s.used[name]; i++ {
		name = fmt.Sprintf("%s%d", base, i)
	}
	s.used[name] = true
	return name
}
